class Solution {
    public boolean makesquare(int[] matchsticks) {
        int total = 0;
        for (int x : matchsticks) total += x;
        if (total % 4 != 0) return false;
        int side = total / 4;
        Arrays.sort(matchsticks);
        for (int i = 0, j = matchsticks.length - 1; i < j; ++i, --j) {
            int tmp = matchsticks[i];
            matchsticks[i] = matchsticks[j];
            matchsticks[j] = tmp;
        }
        if (matchsticks[0] > side) return false;
        int[] sides = new int[4];
        return backtrack(matchsticks, sides, 0, side);
    }
    private boolean backtrack(int[] matchsticks, int[] sides, int index, int target) {
        if (index == matchsticks.length) return true;
        int val = matchsticks[index];
        for (int i = 0; i < 4; ++i) {
            if (sides[i] + val <= target) {
                sides[i] += val;
                if (backtrack(matchsticks, sides, index + 1, target)) return true;
                sides[i] -= val;
            }
            if (sides[i] == 0) break;
        }
        return false;
    }
}

var makesquare = function(matchsticks) {
    const total = matchsticks.reduce((a, b) => a + b, 0);
    if (total % 4 !== 0) return false;
    const side = total / 4;
    matchsticks.sort((a, b) => b - a);
    if (matchsticks[0] > side) return false;
    const sides = [0, 0, 0, 0];
    function backtrack(index) {
        if (index === matchsticks.length) return true;
        const val = matchsticks[index];
        for (let i = 0; i < 4; ++i) {
            if (sides[i] + val <= side) {
                sides[i] += val;
                if (backtrack(index + 1)) return true;
                sides[i] -= val;
            }
            if (sides[i] === 0) break;
        }
        return false;
    }
    return backtrack(0);
};
